using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer.Editor;
public static class ResumeReverseConstruction {
public static string Main(){if(EditorApplication.isCompiling||Application.isPlaying)throw new Exception("Compiled edit mode required");EditorApplication.delayCall+=()=>{try{const string target="Assets/Scenes/DansBackyardReverse.unity";const string source="Assets/Scenes/DansBackyardForward.unity";
if(File.Exists(target)){if(File.ReadAllText(target)!=File.ReadAllText(source))throw new Exception("Reverse contains authored changes; do not discard");EditorSceneManager.OpenScene(source);if(!AssetDatabase.DeleteAsset(target))throw new Exception("Could not remove unchanged initial clone");}
foreach(var file in Directory.GetFiles("Assets/Track/BackyardReverse","DansBackyardReverse-reverse-trail-*.asset")){var path=file.Replace('\\','/');if(AssetDatabase.GetDependencies(source).Contains(path))throw new Exception("Unexpected Forward dependency");AssetDatabase.DeleteAsset(path);}
File.WriteAllText("Docs/BackyardReverse/construction-recovery.txt","First construction stopped in background Editor because unbounded authoring proximity checks scanned unrelated terrain. All world changes were saved. The unfinished Reverse scene was byte-identical to updated Forward; only that clone and three unreferenced generated mesh assets were removed. Rerun uses bounded spatial indexing, unchanged intended geometry.");
BackyardReverseAuthoring.Reverse();File.WriteAllText("Docs/BackyardReverse/reverse-done.txt","Reverse scene saved");}catch(Exception e){File.WriteAllText("Docs/BackyardReverse/reverse-error.txt",e.ToString());}};return "Resume bounded Reverse construction from the saved world";}
}
